    Bug 1949120 - Replace nsMsgDatabase registration in XPCOM. r=BenC
    This adds a build flag specifically for Panorama rather than using the MOZ_NIGHTLY_BUILD.
    It also adds a preference which must be set to use the new database.

    If both the build flag and preference are set, DatabaseCore replaces nsMsgDBService.

    Differential Revision: https://phabricator.services.mozilla.com/D240541

diff --git a/mail/components/MailGlue.sys.mjs b/mail/components/MailGlue.sys.mjs
index 94632d1ce69..bf50b006471 100644
--- a/mail/components/MailGlue.sys.mjs
+++ b/mail/components/MailGlue.sys.mjs
@@ -418,6 +418,30 @@ MailGlue.prototype = {
           "extensions.lastAppVersion",
           "0"
         );
+
+        // Replace the database service with the Panorama database.
+        // This should only happen if MOZ_PANORAMA is true in the build config
+        // (but we can't check that here). Otherwise, if the preference is set
+        // to true, you're gonna have a bad time.
+        if (Services.prefs.getBoolPref("mail.panorama.enabled", false)) {
+          const componentRegistrar = Components.manager.QueryInterface(
+            Ci.nsIComponentRegistrar
+          );
+
+          componentRegistrar.registerFactory(
+            Services.uuid.generateUUID(),
+            "",
+            "@mozilla.org/msgDatabase/msgDBService;1",
+            {
+              createInstance(iid) {
+                return Cc["@mozilla.org/mailnews/database-core;1"].getService(
+                  iid
+                );
+              },
+            }
+          );
+        }
+
         break;
       case "command-line-startup": {
         // Check if this process is the developer toolbox process, and if it
